/* Exact supplied brand logos embedded so this single JSX file is self-contained. */
const REVIEW_PLATFORM_LOGOS = {
  trustpilot: 'data:image/png;base64,',
  clutch: 'data:image/png;base64,',
  glassdoor: 'data:image/png;base64,',
  google: 'data:image/png;base64,',
};

const ADDITIONAL_REVIEW_LOGOS = {
  yelp: 'data:image/png;base64,',
  designrush: 'data:image/png;base64,',
  techreviewer: 'data:image/png;base64,',
  goodfirms: 'data:image/png;base64,',
};
const ADDITIONAL_REVIEW_LABELS = { yelp: 'Yelp', designrush: 'DesignRush', techreviewer: 'Techreviewer', goodfirms: 'GoodFirms' };

function ReviewPlatformLogo({ platform, compact = false }) {
  return (
    <img
      className={`ot-platform-brand-image ot-platform-brand-image--${platform}${compact ? ' is-compact' : ''}`}
      src={REVIEW_PLATFORM_LOGOS[platform]}
      alt={`${REVIEW_PLATFORMS[platform].label} logo`}
      loading="lazy"
      draggable="false"
    />
  );
}

function ReviewStars({ rating, platform }) {
  return (
    <span className={`ot-reviews-stars ot-reviews-stars--${platform}`} role="img" aria-label={`${rating} out of 5 stars`}>
      {Array.from({ length: 5 }, (_, index) => (
        <span className={index < rating ? 'is-filled' : 'is-empty'} key={index} aria-hidden="true">★</span>
      ))}
    </span>
  );
}

function ReviewerAvatar({ review }) {
  const [pictureFailed, setPictureFailed] = useState(false);
  useEffect(() => setPictureFailed(false), [review.avatar]);
  return (
    <span className="ot-review-avatar" aria-label={`${review.name} avatar`}>
      {review.avatar && !pictureFailed ? (
        <img src={review.avatar} alt="" loading="lazy" draggable="false" onError={() => setPictureFailed(true)} />
      ) : review.initials}
    </span>
  );
}

function TrustpilotTestimonials() {
  const [platformKey, setPlatformKey] = useState('trustpilot');
  const [activeIndex, setActiveIndex] = useState(0);
  const [isHovered, setIsHovered] = useState(false);
  const [hasFocus, setHasFocus] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [isVisible, setIsVisible] = useState(true);
  const [interaction, setInteraction] = useState(0);
  const rootRef = useRef(null);
  const pointerStart = useRef(null);
  const platform = REVIEW_PLATFORMS[platformKey];
  const reviews = platform.reviews;
  const hasSlides = reviews.length > 0;

  useEffect(() => {
    if (!rootRef.current || typeof IntersectionObserver === 'undefined') return;
    const observer = new IntersectionObserver(([entry]) => setIsVisible(entry.isIntersecting), { threshold: 0.12 });
    observer.observe(rootRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    if (isHovered || hasFocus || isDragging || !isVisible || reducedMotion || reviews.length < 2) return;
    const timer = window.setInterval(() => {
      setActiveIndex(previous => (previous + 1) % reviews.length);
    }, 5500);
    return () => window.clearInterval(timer);
  }, [platformKey, reviews.length, isHovered, hasFocus, isDragging, isVisible, interaction]);

  const choosePlatform = key => {
    if (key === platformKey) return;
    setPlatformKey(key);
    setActiveIndex(0);
    setInteraction(previous => previous + 1);
    setIsDragging(false);
    pointerStart.current = null;
  };
  const selectSlide = index => {
    if (!reviews.length) return;
    setActiveIndex((index + reviews.length) % reviews.length);
    setInteraction(previous => previous + 1);
  };
  const step = direction => {
    if (!reviews.length) return;
    setActiveIndex(previous => (previous + direction + reviews.length) % reviews.length);
    setInteraction(previous => previous + 1);
  };
  const onPointerDown = event => {
    if (reviews.length < 2 || (event.pointerType === 'mouse' && event.button !== 0)) return;
    pointerStart.current = event.clientX;
    setIsDragging(true);
    event.currentTarget.setPointerCapture?.(event.pointerId);
  };
  const onPointerUp = event => {
    if (pointerStart.current !== null) {
      const delta = event.clientX - pointerStart.current;
      if (Math.abs(delta) >= 45) step(delta < 0 ? 1 : -1);
    }
    pointerStart.current = null;
    setIsDragging(false);
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  };
  const onPointerCancel = () => {
    pointerStart.current = null;
    setIsDragging(false);
  };
  const onPlatformKeyDown = (event, index) => {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    const keys = Object.keys(REVIEW_PLATFORMS);
    const nextIndex = (index + (event.key === 'ArrowRight' ? 1 : -1) + keys.length) % keys.length;
    choosePlatform(keys[nextIndex]);
    event.currentTarget.parentElement?.querySelectorAll('[role="tab"]')[nextIndex]?.focus();
  };

  return (
    <section
      className="ot-reviews-section"
      id="orcanex-testimonials"
      aria-labelledby="ot-reviews-heading"
      ref={rootRef}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onFocusCapture={() => setHasFocus(true)}
      onBlurCapture={event => {
        if (!event.currentTarget.contains(event.relatedTarget)) setHasFocus(false);
      }}
    >
      <div className="ot-reviews-ambient ot-reviews-ambient--one" aria-hidden="true" />
      <div className="ot-reviews-ambient ot-reviews-ambient--two" aria-hidden="true" />
      <div className="ot-reviews-inner">
        <div className="ot-reviews-intro">
          <span className="ot-reviews-eyebrow"><span className="ot-reviews-eyebrow-dot" /> WHAT PEOPLE SAY</span>
          <h2 id="ot-reviews-heading">Real experiences.<br /><span className="ot-heading-feedback">Real feedback.</span></h2>
          <p className="ot-reviews-description" key={`desc-${platformKey}`}>{platform.description}</p>
          <div className="ot-reviews-trustpilot ot-reviews-score-panel" key={`score-${platformKey}`}>
            <ReviewPlatformLogo platform={platformKey} />
            {platform.score ? (
              <div className="ot-reviews-score-row">
                <strong>{platform.score}<span> / 5</span></strong>
                <span className="ot-reviews-score-meta">{platform.scoreName}<br /><b>{platform.count} {platform.count === 1 ? 'review' : 'reviews'}</b></span>
              </div>
            ) : (
              <div className="ot-reviews-unavailable"><strong>Customer reviews</strong><span>View the latest ratings directly on Google</span></div>
            )}
            <p className="ot-reviews-snapshot">{platform.snapshot}</p>
          </div>
          <a className="ot-reviews-profile-link" href={platform.url} target="_blank" rel="noopener noreferrer" key={`link-${platformKey}`}>
            {platformKey === 'glassdoor' ? 'Read employee reviews on Glassdoor' : `See all reviews on ${platform.label}`}
            <span aria-hidden="true">↗</span>
          </a>
        </div>

        <div className="ot-reviews-carousel" aria-roledescription={hasSlides ? 'carousel' : undefined} aria-label={`${platform.label} reviews`}>
          <div className="ot-reviews-carousel-top">
            <span className="ot-reviews-carousel-label"><span /> {platformKey === 'glassdoor' ? 'WORKPLACE FEEDBACK' : 'CUSTOMER STORIES'}</span>
            <div className="ot-reviews-nav">
              <button type="button" onClick={() => step(-1)} disabled={reviews.length < 2} aria-label="Previous review">←</button>
              <button type="button" onClick={() => step(1)} disabled={reviews.length < 2} aria-label="Next review">→</button>
            </div>
          </div>
          <div className="ot-reviews-slide-wrapper" key={`slide-${platformKey}`} id="ot-reviews-platform-panel" role="tabpanel" aria-label={`${platform.label} feedback`}>
            {hasSlides ? (
              <div
                className={`ot-reviews-viewport${isDragging ? ' is-dragging' : ''}`}
                onPointerDown={onPointerDown}
                onPointerUp={onPointerUp}
                onPointerCancel={onPointerCancel}
                onLostPointerCapture={onPointerCancel}
              >
                <div className="ot-reviews-track" style={{ transform: `translate3d(-${activeIndex * 100}%, 0, 0)` }}>
                  {reviews.map((review, index) => (
                    <article
                      className="ot-review-card"
                      role="group"
                      aria-roledescription="slide"
                      aria-label={`Review ${index + 1} of ${reviews.length}`}
                      aria-hidden={activeIndex !== index}
                      key={`${platformKey}-${review.name}`}
                    >
                      <div className="ot-review-topline">
                        <ReviewStars rating={review.rating} platform={platformKey} />
                        <span className="ot-review-source">{platform.label.toUpperCase()} REVIEW</span>
                      </div>
                      <span className="ot-review-quote-mark" aria-hidden="true">“</span>
                      <div className="ot-review-content">
                        {review.title && <span className="ot-review-title">{review.title}</span>}
                        <blockquote className="ot-review-quote">{review.text}</blockquote>
                        {review.isSummary && <span className="ot-review-summary-note">{platformKey === 'glassdoor' ? 'Summary of employee review' : 'Summary of customer review'}</span>}
                      </div>
                      <div className="ot-review-bottom">
                        <div className="ot-review-author">
                          <strong>{review.name}</strong>
                          <span>{review.meta} <span aria-hidden="true">·</span> {review.date}</span>
                        </div>
                        <ReviewerAvatar review={review} />
                      </div>
                    </article>
                  ))}
                </div>
              </div>
            ) : (
              <div className="ot-review-card ot-review-empty">
                <ReviewPlatformLogo platform={platformKey} compact />
                <span className="ot-review-empty-icon" aria-hidden="true">✦</span>
                <h3>Explore Orcanex reviews on Google</h3>
                <p>Google reviews are displayed on the business profile. Open Google to see the latest ratings and customer feedback directly from the source.</p>
                <a href={platform.url} target="_blank" rel="noopener noreferrer">View reviews on Google <span aria-hidden="true">↗</span></a>
              </div>
            )}
          </div>
          <div className="ot-reviews-carousel-bottom">
            <div className="ot-reviews-dots" aria-label="Choose a testimonial">
              {reviews.map((review, index) => (
                <button
                  type="button"
                  key={`${platformKey}-${review.name}`}
                  className={index === activeIndex ? 'is-active' : ''}
                  aria-label={`Go to ${review.name}'s review`}
                  aria-pressed={index === activeIndex}
                  onClick={() => selectSlide(index)}
                />
              ))}
            </div>
            <span className="ot-reviews-slide-count">
              {hasSlides ? <>{String(activeIndex + 1).padStart(2, '0')} <span>/</span> {String(reviews.length).padStart(2, '0')}</> : 'NO PUBLIC REVIEWS'}
            </span>
          </div>
        </div>
      </div>

      <div className="ot-platform-switcher">
        <p className="ot-platform-heading">EXPLORE REVIEWS BY PLATFORM</p>
        <div className="ot-platform-tabs" role="tablist" aria-label="Choose review platform">
          {Object.keys(REVIEW_PLATFORMS).map((key, index) => (
            <button
              type="button"
              role="tab"
              key={key}
              className={`ot-platform-tab${platformKey === key ? ' is-selected' : ''}`}
              aria-selected={platformKey === key}
              aria-controls="ot-reviews-platform-panel"
              tabIndex={platformKey === key ? 0 : -1}
              onKeyDown={event => onPlatformKeyDown(event, index)}
              onClick={() => choosePlatform(key)}
            >
              <ReviewPlatformLogo platform={key} compact />
              <span className="ot-platform-tab-hint">{platformKey === key ? 'Viewing reviews' : 'Click to view'}</span>
              <span className="ot-platform-tab-indicator" aria-hidden="true" />
            </button>
          ))}
        </div>
        {/* <span className="ot-platform-switch-help">Select a platform to switch the reviews above <span aria-hidden="true">↑</span></span>
        <div className="ot-platform-more" aria-label="Other review directory logos">
          {['yelp','designrush','techreviewer','goodfirms'].map(key => (
            <span className="ot-platform-more-logo" key={key} title="Profile URL not provided">
              <img src={ADDITIONAL_REVIEW_LOGOS[key]} alt={`${ADDITIONAL_REVIEW_LABELS[key]} logo`} loading="lazy" draggable="false" />
            </span>
          ))}
        </div> */}

      </div>
    </section>
  );
}

