const page = {
  route: "/",
  source: "index.html",
  title: "Web Design Melbourne | Web Development Company Melbourne",
  bodyClass: "home wp-singular page-template-default page page-id-217 wp-theme-chromatix-2018 wp-child-theme-chromatix-2018-child",
  sections: [homeHtml],
  stylesheets: [
    "https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500;600&display=swap",
    "https://cdn.jsdelivr.net/npm/bootstrap@5.0.2/dist/css/bootstrap.min.css",
    "/wp-content/plugins/chromatix-social-media-icons/dist/styles.min4c56.css?ver=2.0.2",
    "/wp-content/themes/chromatix-2018-child/dist/css/fonts.minc520.css?ver=1.50.7",
    "/wp-content/themes/chromatix-2018-child/libs/ion.rangeSlider-2.2.0.min.css",
    "/wp-content/themes/chromatix-2018-child/dist/css/home.minc520.css?ver=1.50.7",
    "/wp-content/themes/chromatix-2018-child/dist/css/portfolio.minc520.css?ver=1.50.7"
  ],
  inlineCss: `${pageCss}
${portfolioCss}
${homePortfolioCss}
${trustpilotCss}`,
  scriptPlan: [
    { type: "src", value: "/wp-content/themes/chromatix-2018-child/dist/js/home-lazy-video.min.js" },
    { type: "src", value: "/wp-content/themes/chromatix-2018-child/dist/js/home.minc520.js?ver=1.50.7" },
    {
      type: "inline", value: String.raw`/* Home portfolio filters + full-page preview hover measurement. */
(function () {
  'use strict';

  const portfolio = document.getElementById('portfolio-new');
  if (!portfolio) return;

  const cards = Array.from(portfolio.querySelectorAll('.project-card'));
  const filters = Array.from(portfolio.querySelectorAll('.filter-button'));
  const resultCount = portfolio.querySelector('#portfolio-result-count');
  const emptyState = portfolio.querySelector('#portfolio-empty');

  function visibleCards() {
    return cards.filter(function (card) { return !card.hidden; });
  }

  function measureImage(card) {
    const image = card.querySelector('.project-image');
    const viewport = card.querySelector('.project-screen');
    if (!image || !viewport || card.hidden || !image.naturalWidth || !viewport.clientWidth) return;

    const scaledHeight = image.naturalHeight * viewport.clientWidth / image.naturalWidth;
    const distance = Math.max(0, scaledHeight - viewport.clientHeight);
    card.classList.toggle('is-short', distance <= 2);
    card.style.setProperty('--scroll-distance', distance.toFixed(1) + 'px');
    const seconds = Math.max(4.5, Math.min(15, distance / 165));
    card.style.setProperty('--auto-scroll-duration', seconds.toFixed(2) + 's');
  }

  function measureVisibleCards() {
    requestAnimationFrame(function () {
      visibleCards().forEach(measureImage);
    });
  }

  function setCategory(category) {
    let visible = 0;
    cards.forEach(function (card) {
      const match = category === 'All' || card.dataset.category === category;
      card.hidden = !match;
      if (match) visible += 1;
    });

    filters.forEach(function (button) {
      const selected = button.dataset.filter === category;
      button.setAttribute('aria-pressed', String(selected));
      button.classList.toggle('is-active', selected);
    });

    if (emptyState) emptyState.hidden = visible > 0;
    if (resultCount) {
      resultCount.textContent = visible + (visible === 1 ? ' project' : ' projects') +
        ' shown' + (category === 'All' ? '.' : ' in ' + category + '.');
    }
    measureVisibleCards();
  }

  filters.forEach(function (button) {
    button.addEventListener('click', function () {
      setCategory(button.dataset.filter || 'All');
    });
  });

  cards.forEach(function (card) {
    const image = card.querySelector('.project-image');
    const placeholder = card.querySelector('.project-placeholder');
    if (!image) return;

    function loaded() {
      image.hidden = false;
      if (placeholder) placeholder.hidden = true;
      measureImage(card);
    }

    function failed() {
      image.hidden = true;
      if (placeholder) placeholder.hidden = false;
      card.classList.add('is-short');
      card.style.setProperty('--scroll-distance', '0px');
    }

    image.addEventListener('load', loaded);
    image.addEventListener('error', failed);
    if (image.complete) image.naturalWidth ? loaded() : failed();

    card.addEventListener('pointerenter', function () { measureImage(card); });
    const link = card.querySelector('.project-open');
    if (link) {
      link.addEventListener('focus', function () { measureImage(card); });
      link.addEventListener('click', function (event) {
        event.preventDefault();

        const source = image.currentSrc || image.getAttribute('src');
        if (!source) return;

        const overlay = document.createElement('div');
        overlay.className = 'home-portfolio-lightbox';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.innerHTML =
          '<button class="home-portfolio-lightbox__close" type="button" aria-label="Close image preview">×</button>' +
          '<div class="home-portfolio-lightbox__inner"><img alt="' +
          (image.getAttribute('alt') || 'Portfolio preview').replace(/"/g, '&quot;') +
          '" src="' + source + '"/></div>';

        function closePreview() {
          overlay.remove();
          document.body.classList.remove('home-portfolio-lightbox-open');
          document.removeEventListener('keydown', onKeyDown);
        }

        function onKeyDown(event) {
          if (event.key === 'Escape') closePreview();
        }

        overlay.addEventListener('click', function (event) {
          if (event.target === overlay || event.target.closest('.home-portfolio-lightbox__close')) {
            closePreview();
          }
        });

        document.body.appendChild(overlay);
        document.body.classList.add('home-portfolio-lightbox-open');
        document.addEventListener('keydown', onKeyDown);
      });
    }
  });

  if ('ResizeObserver' in window) {
    const observer = new ResizeObserver(function () { measureVisibleCards(); });
    cards.forEach(function (card) {
      const viewport = card.querySelector('.project-screen');
      if (viewport) observer.observe(viewport);
    });
  } else {
    window.addEventListener('resize', measureVisibleCards, { passive: true });
  }

  setCategory('All');
}());` },
    {
      type: "inline", value: String.raw`/* Growth statistics counter */
(function () {
  const section = document.getElementById('chr-section-two');
  if (!section) return;
  const counters = Array.from(section.querySelectorAll('.orcanex-counter[data-count]'));
  if (!counters.length) return;
  let played = false;
  function run() {
    if (played) return;
    played = true;
    const duration = 1700;
    counters.forEach(function (node) {
      const target = Number(node.getAttribute('data-count') || 0);
      const start = performance.now();
      function frame(now) {
        const progress = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - progress, 3);
        node.textContent = String(Math.round(target * eased));
        if (progress < 1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    });
  }
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(function (entries) {
      if (entries.some(function (entry) { return entry.isIntersecting; })) {
        run(); observer.disconnect();
      }
    }, { threshold: .3 });
    observer.observe(section);
  } else { run(); }
}());` },
  ],
};

function HomeReactSections() {
  const [targets, setTargets] = useState({ pricing: null, combo: null, portfolio: null, testimonials: null, caseStudies: null });

  useLayoutEffect(() => {
    setTargets({
      pricing: document.getElementById('pricing-plans-react-root'),
      combo: document.getElementById('all-in-one-combo-react-root'),
      portfolio: document.getElementById('home-portfolio-explorer-root'),
      caseStudies: document.getElementById('home-case-studies-react-root'),
      testimonials: document.getElementById('home-trustpilot-react-root'),
    });
  }, []);

  return <>
    {targets.portfolio && createPortal(<PortfolioExplorer compact />, targets.portfolio)}
    {targets.caseStudies && createPortal(<CaseStudyHomeSection />, targets.caseStudies)}
    {targets.pricing && createPortal(<PricingPlans />, targets.pricing)}
    {targets.combo && createPortal(<AllInOneCombo />, targets.combo)}
    {targets.testimonials && createPortal(<TrustpilotTestimonials />, targets.testimonials)}
  </>;
}

export default function HomePage() {
  return <>
    <PageLayout page={page} />
    <HomeReactSections />
  </>;
}
